const BirdSprite* birdSprite(const char* name) {
  for (int i = 0; i < N_BIRD_SPRITES; i++)
    if (strcmp(BIRD_SPRITES[i].name, name) == 0) return &BIRD_SPRITES[i];
  return nullptr;
}
